{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2131-04-27 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning, Mr. Thompson. I'm Dr. Patel, one of your hospitalists. You're here today for your maintenance high-dose methotrexate infusion, correct?"
    },
    {
      "turn_number": 2,
      "time": "2131-04-27 08:16:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. My tenth cycle since the relapse. I’ve been doing okay between treatments."
    },
    {
      "turn_number": 3,
      "time": "2131-04-27 08:17:00",
      "speaker": "Doctor",
      "text": "Good to hear. We’ll be giving you 8 grams per square meter today. You’ve tolerated it well in the past, so we expect the same."
    },
    {
      "turn_number": 4,
      "time": "2131-04-27 08:18:00",
      "speaker": "Patient",
      "text": "I usually feel tired for a couple days after, but then I’m back to work. I’m still doing three days a week at the auto shop."
    },
    {
      "turn_number": 5,
      "time": "2131-04-27 08:19:00",
      "speaker": "Doctor",
      "text": "That’s great progress. We’ll monitor your labs closely, especially your methotrexate levels, to make sure it clears safely."
    },
    {
      "turn_number": 6,
      "time": "2131-04-27 08:20:00",
      "speaker": "Patient",
      "text": "And the leucovorin? That helps with the side effects, right?"
    },
    {
      "turn_number": 7,
      "time": "2131-04-27 08:21:00",
      "speaker": "Doctor",
      "text": "Exactly. We start leucovorin 24 hours after the infusion to protect your cells. We’ll keep giving it until your methotrexate level drops below 0.1."
    },
    {
      "turn_number": 8,
      "time": "2131-04-27 08:22:00",
      "speaker": "Patient",
      "text": "Got it. And I know we hold some of my regular meds during treatment?"
    },
    {
      "turn_number": 9,
      "time": "2131-04-27 08:23:00",
      "speaker": "Doctor",
      "text": "Yes, we pause aspirin and omeprazole while you’re on methotrexate. We don’t want any kidney or stomach irritation. We’ll restart them when you go home."
    },
    {
      "turn_number": 10,
      "time": "2131-04-27 08:24:00",
      "speaker": "Patient",
      "text": "Makes sense. What about the fluconazole for my rash?"
    },
    {
      "turn_number": 11,
      "time": "2131-04-27 08:25:00",
      "speaker": "Doctor",
      "text": "We’re holding that during the infusion too, since it can affect liver enzymes. But we’ll restart it once you’re stable."
    },
    {
      "turn_number": 12,
      "time": "2131-04-27 08:26:00",
      "speaker": "Patient",
      "text": "The rash on my chest has been much better, though. Almost gone."
    },
    {
      "turn_number": 13,
      "time": "2131-04-27 08:27:00",
      "speaker": "Doctor",
      "text": "That’s excellent. The fluconazole’s been helping. We’ll keep it up after discharge."
    },
    {
      "turn_number": 14,
      "time": "2131-04-27 12:15:00",
      "speaker": "Doctor",
      "text": "Hi again, Mr. Thompson. You’re about halfway through the methotrexate infusion. How are you feeling?"
    },
    {
      "turn_number": 15,
      "time": "2131-04-27 12:16:00",
      "speaker": "Patient",
      "text": "Pretty good. No nausea or headache. Just a little tired, but that’s normal."
    },
    {
      "turn_number": 16,
      "time": "2131-04-27 12:17:00",
      "speaker": "Doctor",
      "text": "Good. We’re keeping your urine pH above 7.5 with sodium bicarbonate to protect your kidneys. That’s going well."
    },
    {
      "turn_number": 17,
      "time": "2131-04-27 12:18:00",
      "speaker": "Patient",
      "text": "I remember that from last time. It’s important to flush the drug out safely."
    },
    {
      "turn_number": 18,
      "time": "2131-04-27 12:19:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ll keep monitoring your labs over the next few days."
    },
    {
      "turn_number": 19,
      "time": "2131-04-28 09:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your first methotrexate level came back at 2.2, which is expected this early. Liver enzymes are a bit up, but that’s typical."
    },
    {
      "turn_number": 20,
      "time": "2131-04-28 09:01:00",
      "speaker": "Patient",
      "text": "Is that a concern?"
    },
    {
      "turn_number": 21,
      "time": "2131-04-28 09:02:00",
      "speaker": "Doctor",
      "text": "Not at this stage. We expect a temporary rise. We’ll keep an eye on it and continue leucovorin."
    },
    {
      "turn_number": 22,
      "time": "2131-04-28 09:03:00",
      "speaker": "Patient",
      "text": "Okay, good. Any word on when I might be able to go home?"
    },
    {
      "turn_number": 23,
      "time": "2131-04-28 09:04:00",
      "speaker": "Doctor",
      "text": "Likely in a couple of days, once your level drops below 0.1 and we’re sure you’re stable."
    },
    {
      "turn_number": 24,
      "time": "2131-04-29 10:00:00",
      "speaker": "Doctor",
      "text": "Hi. We’re scheduling your brain MRI today for restaging. Any headaches or vision changes?"
    },
    {
      "turn_number": 25,
      "time": "2131-04-29 10:01:00",
      "speaker": "Patient",
      "text": "No, nothing new. I’ve been feeling steady."
    },
    {
      "turn_number": 26,
      "time": "2131-04-29 10:02:00",
      "speaker": "Doctor",
      "text": "Good. The MRI will help confirm the lymphoma is still in remission."
    },
    {
      "turn_number": 27,
      "time": "2131-04-30 17:30:00",
      "speaker": "Doctor",
      "text": "Mr. Thompson, the MRI results are back. No new enhancing lesions. The old lesion in your brain is stable."
    },
    {
      "turn_number": 28,
      "time": "2131-04-30 17:31:00",
      "speaker": "Patient",
      "text": "That’s a relief. So no sign of recurrence?"
    },
    {
      "turn_number": 29,
      "time": "2131-04-30 17:32:00",
      "speaker": "Doctor",
      "text": "None. The radiologist says it looks stable, which is exactly what we want to see."
    },
    {
      "turn_number": 30,
      "time": "2131-04-30 17:33:00",
      "speaker": "Patient",
      "text": "Great. Does that mean I can go home soon?"
    },
    {
      "turn_number": 31,
      "time": "2131-04-30 17:34:00",
      "speaker": "Doctor",
      "text": "Yes, we’re planning for discharge tomorrow. Your methotrexate level is now 0.06, which is safe."
    },
    {
      "turn_number": 32,
      "time": "2131-04-30 17:35:00",
      "speaker": "Patient",
      "text": "That’s good. I’ve lost a little weight, though."
    },
    {
      "turn_number": 33,
      "time": "2131-04-30 17:36:00",
      "speaker": "Doctor",
      "text": "Yes, the nurse noted you’re down a few pounds, but that’s common after treatment. Just focus on eating well when you’re home."
    },
    {
      "turn_number": 34,
      "time": "2131-04-30 17:37:00",
      "speaker": "Patient",
      "text": "I will. Any changes to my meds?"
    },
    {
      "turn_number": 35,
      "time": "2131-04-30 17:38:00",
      "speaker": "Doctor",
      "text": "We’ll restart aspirin and omeprazole tomorrow. Fluconazole too, to finish clearing the rash."
    },
    {
      "turn_number": 36,
      "time": "2131-04-30 17:39:00",
      "speaker": "Patient",
      "text": "And the docusate and magnesium for constipation?"
    },
    {
      "turn_number": 37,
      "time": "2131-04-30 17:40:00",
      "speaker": "Doctor",
      "text": "Yes, continue those as needed. We’ll send more home with you."
    },
    {
      "turn_number": 38,
      "time": "2131-05-01 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge. Your labs are stable, and you’re neurologically intact."
    },
    {
      "turn_number": 39,
      "time": "2131-05-01 08:01:00",
      "speaker": "Patient",
      "text": "That’s great. When’s my next follow-up?"
    },
    {
      "turn_number": 40,
      "time": "2131-05-01 08:02:00",
      "speaker": "Doctor",
      "text": "Your oncologist will see you in three months for the next MRI. They’ll call if anything changes."
    },
    {
      "turn_number": 41,
      "time": "2131-05-01 08:03:00",
      "speaker": "Patient",
      "text": "And the methotrexate cycles? Are we still on the bimonthly schedule?"
    },
    {
      "turn_number": 42,
      "time": "2131-05-01 08:04:00",
      "speaker": "Doctor",
      "text": "For now, yes. But the next one may be spaced further out, depending on how you continue to do."
    },
    {
      "turn_number": 43,
      "time": "2131-05-01 08:05:00",
      "speaker": "Patient",
      "text": "That’d be nice. Less time away from work."
    },
    {
      "turn_number": 44,
      "time": "2131-05-01 08:06:00",
      "speaker": "Doctor",
      "text": "We’ll see. Just keep up with the meds and let us know if you develop any new symptoms—like headaches, weakness, or nausea."
    },
    {
      "turn_number": 45,
      "time": "2131-05-01 08:07:00",
      "speaker": "Patient",
      "text": "I will. And if the rash comes back?"
    },
    {
      "turn_number": 46,
      "time": "2131-05-01 08:08:00",
      "speaker": "Doctor",
      "text": "Continue the fluconazole. If it worsens, call your doctor."
    },
    {
      "turn_number": 47,
      "time": "2131-05-01 08:09:00",
      "speaker": "Patient",
      "text": "Got it. Thanks for all the help."
    },
    {
      "turn_number": 48,
      "time": "2131-05-01 08:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You’ve done really well with this cycle. Keep up the good work."
    },
    {
      "turn_number": 49,
      "time": "2131-05-01 08:11:00",
      "speaker": "Patient",
      "text": "I’ll try. It’s not easy, but I’m managing."
    },
    {
      "turn_number": 50,
      "time": "2131-05-01 08:12:00",
      "speaker": "Doctor",
      "text": "You’re doing better than most. We’ll see you in follow-up."
    },
    {
      "turn_number": 51,
      "time": "2131-05-01 08:13:00",
      "speaker": "Patient",
      "text": "One more thing—my dad and brothers all had heart issues. Should I worry more?"
    },
    {
      "turn_number": 52,
      "time": "2131-05-01 08:14:00",
      "speaker": "Doctor",
      "text": "You’re already on aspirin, which helps. Keep your cholesterol in check and stay active. We’ll monitor your heart health."
    },
    {
      "turn_number": 53,
      "time": "2131-05-01 08:15:00",
      "speaker": "Patient",
      "text": "Okay, I’ll keep that in mind."
    },
    {
      "turn_number": 54,
      "time": "2131-05-01 08:16:00",
      "speaker": "Doctor",
      "text": "And don’t forget to hydrate well, especially after chemo."
    },
    {
      "turn_number": 55,
      "time": "2131-05-01 08:17:00",
      "speaker": "Patient",
      "text": "I’ve been drinking extra water. Helps with the fatigue too."
    },
    {
      "turn_number": 56,
      "time": "2131-05-01 08:18:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re doing all the right things."
    },
    {
      "turn_number": 57,
      "time": "2131-05-01 08:19:00",
      "speaker": "Patient",
      "text": "Thanks, doc. I appreciate it."
    },
    {
      "turn_number": 58,
      "time": "2131-05-01 08:20:00",
      "speaker": "Doctor",
      "text": "We’ll get your discharge papers ready. You can head home in about an hour."
    },
    {
      "turn_number": 59,
      "time": "2131-05-01 08:21:00",
      "speaker": "Patient",
      "text": "Looking forward to it. Thanks again."
    },
    {
      "turn_number": 60,
      "time": "2131-05-01 08:22:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. Thompson. Call if anything comes up."
    },
    {
      "turn_number": 61,
      "time": "2131-05-01 08:23:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 62,
      "time": "2131-05-01 08:24:00",
      "speaker": "Doctor",
      "text": "And keep up with your neuro checks—no dizziness or balance issues?"
    },
    {
      "turn_number": 63,
      "time": "2131-05-01 08:25:00",
      "speaker": "Patient",
      "text": "No, I’ve been steady on my feet. No vertigo lately."
    },
    {
      "turn_number": 64,
      "time": "2131-05-01 08:26:00",
      "speaker": "Doctor",
      "text": "Good. That’s one less thing to worry about."
    },
    {
      "turn_number": 65,
      "time": "2131-05-01 08:27:00",
      "speaker": "Patient",
      "text": "I’ve been careful, especially at work."
    },
    {
      "turn_number": 66,
      "time": "2131-05-01 08:28:00",
      "speaker": "Doctor",
      "text": "Smart. Safety first."
    },
    {
      "turn_number": 67,
      "time": "2131-05-01 08:29:00",
      "speaker": "Patient",
      "text": "Thanks for everything."
    },
    {
      "turn_number": 68,
      "time": "2131-05-01 08:30:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    },
    {
      "turn_number": 69,
      "time": "2131-05-01 08:31:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 70,
      "time": "2131-05-01 08:32:00",
      "speaker": "Doctor",
      "text": "We’ll see you in follow-up."
    }
  ],
  "summary": {
    "admission_start": "2131-04-27 08:06:00",
    "admission_end": "2131-05-01 10:15:00",
    "summary_paragraph": "Mr. Thompson was admitted for his tenth cycle of high-dose methotrexate since CNS lymphoma relapse, marking the sixth maintenance dose and third bimonthly administration. He tolerated the chemotherapy infusion well without complications. His candidal chest rash continued to improve, and he remained neurologically stable with no new deficits. Methotrexate levels were monitored and cleared appropriately, reaching 0.06 before discharge. Liver enzymes rose transiently as expected. Aspirin, omeprazole, and fluconazole were held during treatment and restarted at discharge. A brain MRI showed no new enhancing lesions, indicating stable disease. He was discharged home in stable condition with follow-up scheduled in three months.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Hodgkin's disease, unspecified type, unspecified site, extranodal and solid organ sites",
      "Other malignant lymphomas, unspecified site, extranodal and solid organ sites",
      "Candidiasis of skin and nails",
      "Esophageal reflux",
      "Coronary atherosclerosis of native coronary artery",
      "Other and unspecified hyperlipidemia",
      "Dizziness and giddiness",
      "Other malaise and fatigue",
      "Long-term (current) use of aspirin",
      "Personal history of tuberculosis"
    ]
  }
}
